Lemma FT_tab_reads : forall m (i : Z), rw_cells bsegs m AG_FIELD_TABLE FTCells -> 0 <= i < 130 ->
  ov_read_bytes bsegs m (Z_to_bv 64 (AG_FIELD_TABLE + 16 * i)) 8 = Some (le8 (wz (ft_ptr (Z.to_nat i))))
  /\ ov_read_bytes bsegs m (Z_to_bv 64 (AG_FIELD_TABLE + 16 * i + 8)) 8 = Some (le8 (wz (ft_len (Z.to_nat i)))).
Proof.
  intros m i C Hi. pose proof (rw_cells_bytes_at _ _ _ _ C) as B. unfold FTCells in B. cbn [cells_bytes cbytes] in B.
  apply bytes_at_app in B. destruct B as [B _]. unfold FT_TAB_BYTES in B.
  destruct (nth_error FT_BYNAME (Z.to_nat i)) as [pl|] eqn:N.
  2:{ exfalso. apply nth_error_None in N. rewrite FT_BYNAME_length in N. lia. }
  destruct (ft_words_nth FT_BYNAME (Z.to_nat i) pl N) as [N1 N2]. fold ft_words in N1, N2.
  unfold ft_ptr, ft_len. rewrite (nth_error_nth _ _ _ N). split.
  - replace (AG_FIELD_TABLE + 16 * i) with (AG_FIELD_TABLE + 8 * Z.of_nat (2 * Z.to_nat i)) by lia.
    exact (bytes_at_u64_read _ _ _ _ _ B N1).
  - replace (AG_FIELD_TABLE + 16 * i + 8) with (AG_FIELD_TABLE + 8 * Z.of_nat (2 * Z.to_nat i + 1)) by lia.
    exact (bytes_at_u64_read _ _ _ _ _ B N2).
Qed.

Lemma FT_map_read : forall m (j : Z), rw_cells bsegs m AG_FIELD_TABLE FTCells -> 0 <= j < 1367 ->
  ov_read_bytes bsegs m (Z_to_bv 64 (AG_FIELD_TABLE + 2080 + j)) 1 = Some [b8 (nth (Z.to_nat j) FT_MAP 0)].
Proof.
  intros m j C Hj. pose proof (rw_cells_bytes_at _ _ _ _ C) as B. unfold FTCells in B. cbn [cells_bytes cbytes] in B.
  apply bytes_at_app in B. destruct B as [_ B]. apply bytes_at_app in B. destruct B as [B _].
  rewrite FT_TAB_BYTES_length in B. change (Z.of_nat 2080) with 2080 in B.
  destruct (nth_error FT_MAP (Z.to_nat j)) as [v|] eqn:N.
  2:{ exfalso. apply nth_error_None in N. rewrite FT_MAP_length in N. lia. }
  apply (u8ro_read bsegs m (AG_FIELD_TABLE + 2080) FT_MAP_BYTES j); [exact B | | lia | symmetry; apply wa_of_Z_to_bv; unfold AG_FIELD_TABLE; lia].
  unfold FT_MAP_BYTES. rewrite (nth_error_map b8 (Z.to_nat j) FT_MAP), N. cbn [option_map].
  rewrite (nth_error_nth _ _ _ N). reflexivity.
Qed.

(* [comment removed for export] *)
Lemma FT_shadow0 : forall m x, ACONST m -> AG_FIELD_TABLE <= x < AG_FIELD_TABLE + 3456 ->
  ov_read_bytes bsegs m (Z_to_bv 64 (Z.shiftr x 3 + 2147450880)) 1 = Some [b8 0].
Proof.
  intros m x AC Hx. apply (accessible_read0_in m AG_FIELD_TABLE 3456 x (ft_tab_accessible m AC)); [reflexivity | reflexivity | exact Hx].
Qed.

(* [comment removed for export] *)
(* [comment removed for export] *)

Definition AS2F_STACK : Z := 48 + AEQ_STACK.

Definition s2f_post_v (v : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz v) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ bytes_at bsegs m' P bs /\ FT m'
    /\ ACONST m' /\ accessible m' P (Z.of_nat (length bs)).

Definition s2f_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  s2f_post_v (ft_lookup (zbytes bs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m.

(* [comment removed for export] *)
Definition s2f_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo : Z) (bs : list byte),
  bytes_at bsegs m P bs -> FT m -> P + Z.of_nat (length bs) < 2^64 ->
  stk bsegs m lo (bv_unsigned sp) -> lo + AS2F_STACK <= bv_unsigned sp -> aceil <= lo ->
  (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo) ->
  mem_inv bsegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m P (Z.of_nat (length bs)) ->
  (* [comment removed for export] *)
  (0 < Z.of_nat (length bs) -> 0 < P) ->
  evt bsegs (s2f_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz AG_FIELD_TABLE) (wz P) (wz (Z.of_nat (length bs))) a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_STRING_TO_FIELD) fc None m (seg_rom bsegs)).

Definition s2_ctx (m m1 : mem) (sp s0v s1v s2v s3v s4v rav : word) (P lo : Z) (bs : list byte) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -48) [C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ bytes_at bsegs m1 P bs
  /\ rw_cells bsegs m1 AG_FIELD_TABLE FTCells /\ rw_cells bsegs m1 AG_FIELD_TABLE_GUARD FTGuardCells
  /\ stk bsegs m1 lo (bv_unsigned sp + -48)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ dg_side m P (Z.of_nat (length bs)).

Definition s2_pure (sp : word) (P lo : Z) (bs : list byte) : Prop :=
  P + Z.of_nat (length bs) < 2^64 /\ lo + AS2F_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo)
  /\ (0 < Z.of_nat (length bs) -> 0 < P).

End S2F.

Ltac s2_open CTX PURE :=
  destruct CTX as (FR & WIN & C1 & C2 & ST & MU & WM & MI & SD);
  destruct PURE as (WEND & LO & CEIL & SEPS & PNZ);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPS;
  unfold FTCells in C1; unfold FTGuardCells in C2;
  unfold AS2F_STACK, AEQ_STACK, AGC_STACK in *.

Section S2F2.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Lemma s2f_exit : forall (v : Z) rax ra sp gp tp t0 t1 t2 s0x s1x a1 a2 a3 a4 a5 a6 a7 s2x s3x s4x s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P lo : Z) (bs : list byte),
  0 <= v < 65536 ->
  s2_ctx m m1 sp s0v s1v s2v s3v s4v ra P lo bs -> s2_pure sp P lo bs ->
  evt bsegs (s2f_post_v v ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 s0x s1x (wz v) a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
